export function membersFor(canton: string, council: CouncilCode): Member[] {
  return MEMBERS.filter((member) => member.canton === canton && member.council === council).sort((a, b) =>
    a.lastName.localeCompare(b.lastName, "de") || a.firstName.localeCompare(b.firstName, "de"),
  );
}

function assertMembers(): void {
  const n = MEMBERS.filter((member) => member.council === "N").length;
  const s = MEMBERS.filter((member) => member.council === "S").length;
  if (n !== 200 || s !== 46) throw new Error(`members N ${n} S ${s}`);
  const ids = new Set(MEMBERS.map((member) => member.id));
  if (ids.size !== 246) throw new Error("duplicate member id");
}

assertMembers();
